    ['To the Forsaken Mines'] = {
        id = 11,
        start_npc = 'Any Bastok Gate Guard',
        start_zone = 'Windurst Waters',
        start_pos = nil,
        description = 'Bring back a rare ore from the Gusgen Mines on the Konschtat Highlands. First ask Davyad, an adventurer residing in the Mines District, how he acquired his load of the ore.',
        reward = 'Rank Points',
        fame = nil,
        fame_level = nil,
        title = nil,
        repeatable = 'Yes',
        previous = {'The Four Musketeers'},
        next = {'Jeuno'},
        requirements = nil,
        walkthrough = 'Trade enough Crystals to the Conquest NPC to raise your Rank bar and unlock the Mission, then accept it from the Gate Guard.\n1. Obtain a Hare Meat .\n2. Speak to Davyad (K-6) in Bastok Mines.\n3. Head to Gusgen Mines from Konschtat Highlands and proceed to (J-7).\n   - You will need Sneak or Silent Oil  in here unless you are of sufficient level, /check the monsters to make sure they are incredibly easy prey or too weak.\n4. Once inside the Mines, follow these directions:\n   - Take a right.\n   - At the next intersection, take a left.\n   - At the fork, take a right, and then another right at the next intersection.\n   - You should be at (J-7).\n     - Take caution of Smothered Schmidt who spawns in the same area at either 0:00, 1:00, or 2:00 when the siren in the zone sounds.\n     - Schmidt was easily killed as a lvl 38 NIN with 4 summoned Trusts.\n     - Wait around for it to depop if it is up. Schmidt doesn\'t drop anything worthwhile.\n5. Trade the Hare Meat  to the ??? to spawn Blind Moby, a Pugil NM.\n   - It will drop an item called Glocolite  (). If you\'re in a party with other players, everyone doing this Mission will require one, so defeat the NM as many times as required.\n   - You must wait 3 minute between pops.\n6. Trade the Glocolite  to any Gate Guard to finish the Mission.',
        notes = nil,
    },
